import{z as s,x as B,o as l,c as p,q as i,j as r,D as e,d as t,s as o,S as n,b as E}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"掩模修复：电子束与纳米机械","description":"","frontmatter":{"title":"掩模修复：电子束与纳米机械","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/mask-repair-ebeam.md","filePath":"litho/mask-repair-ebeam.md","lastUpdated":1791413859000}'),d={name:"litho/mask-repair-ebeam.md"};function m(h,a,C,D,u,S){const A=B("Mermaid");return l(),p("div",null,[a[2]||(a[2]=i('<h1 id="掩模修复-电子束与纳米机械" tabindex="-1">掩模修复：电子束与纳米机械 <a class="header-anchor" href="#掩模修复-电子束与纳米机械" aria-label="Permalink to &quot;掩模修复：电子束与纳米机械&quot;">​</a></h1><div class="epigraph"><p>多余的吸收体可以切掉，缺的可以沉积；修复本身是一次局域图形化，CD 与透射必须回到打印窗口内。</p><footer>—— 对照 e-beam 气体辅助修复与纳米机械（nanomachining）的掩模厂通称</footer></div><p><a href="/litho/mask-inspection-d2d-d2db">上一课</a>给出缺陷清单。缺口是哪些能修、用什么刀。本课钉电子束修复与纳米机械。修完要装薄膜，留给<a href="/litho/pellicle-mount-inspect">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>亮缺陷（缺铬/缺吸收体）与暗缺陷（多余材料）的工艺相反：前者要沉积（碳、金属等前体，电子束诱导），后者要去掉（气体辅助刻蚀或金刚石针纳米机械）。修完的补丁在光学上很少与原膜完全一样：透过、相位、三维形状不同，所以必须用打印视角验收（后课 AIMS），不能只看 SEM「看起来平了」。</p><p>缺口是<strong>局域再图形化</strong>，不是检验灵敏度。把所有缺陷当报废，周期与成本炸；把所有缺陷当可修，会留下打印残差。</p><h3 id="euv-与-duv-的刀不同" tabindex="-1">EUV 与 DUV 的刀不同 <a class="header-anchor" href="#euv-与-duv-的刀不同" aria-label="Permalink to &quot;EUV 与 DUV 的刀不同&quot;">​</a></h3><p>EUV 多层一旦被挖穿或氧化，不是表面补一块铬能恢复布拉格反射。<a href="/litho/euv-mask-repair">EUV 掩模修复</a> 有专门约束；本课通称仍适用「沉积/去除 + 打印验收」，但多层损伤往往不可修或只能降级使用。</p><p><span class="marginnote">纳米机械适合相对大的多余铬；极小的针孔更常走电子束。选择按缺陷尺寸、膜系与是否已装 pellicle（装后更难修）。</span></p><p><span class="marginnote">亮/暗只是检测图像里的灰度说法：该挡光的地方漏了光（缺吸收体）是亮缺陷，该透光的地方被堵住（多余材料）是暗缺陷。所以修复动作天然成对——暗的做减法刻掉，亮的做加法沉积补上，工具与验收都要分开选。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>流程：分类 → 选工具 → 修 → 再检验 → AIMS（关键缺陷）。剂量与针轨迹要补偿邻近：修复束自己也有 PEC 问题。多次修复在同一点会累积损伤与污染，有次数上限。</p><p>与 CDU：大面积修复改变局部开口率，长程 PEC 意义下的环境变了——通常可忽略，除非修的是大垫或大缺口。</p>',13)),(l(),r(n,null,{default:e(()=>[o(A,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20LR%0A%20%20R0%5B%22%E7%AC%AC%E4%B8%80%E6%AC%A1%E4%BF%AE%E5%A4%8D%22%5D%20--%3E%20CHK%5B%22%E5%86%8D%E6%A3%80%E9%AA%8C%3A%20SEM%20%E9%87%8F%E5%B0%BA%E5%AF%B8%22%5D%0A%20%20CHK%20--%3E%20OK%5B%22%E5%BD%A2%E8%B2%8C%E5%90%88%E6%A0%BC%22%5D%20--%3E%20AIM%5B%22AIMS%20%E6%89%93%E5%8D%B0%E9%AA%8C%E6%94%B6%22%5D%0A%20%20CHK%20--%3E%20NG%5B%22%E8%BF%87%E5%88%87%20%2F%20%E5%81%8F%E7%A7%BB%20%2F%20%E6%AE%8B%E7%95%99%22%5D%20--%3E%20RETRY%5B%22%E8%B0%83%E5%89%82%E9%87%8F%E6%88%96%E9%92%88%E8%BD%A8%E8%BF%B9%E5%86%8D%E4%BF%AE%22%5D%0A%20%20RETRY%20--%3E%20Q%7B%22%E5%90%8C%E4%B8%80%E7%82%B9%E6%AC%A1%E6%95%B0%E6%9C%AA%E8%B6%85%E4%B8%8A%E9%99%90%3F%22%7D%0A%20%20Q%20--%3E%7C%22%E6%98%AF%22%7C%20R0%0A%20%20Q%20--%3E%7C%22%E5%90%A6%22%7C%20SCRAP%5B%22%E9%99%8D%E7%BA%A7%E6%88%96%E6%8A%A5%E5%BA%9F%22%5D%0A%20%20AIM%20--%3E%7C%22%E4%B8%8D%E8%BF%87%22%7C%20SCRAP%0A%20%20AIM%20--%3E%7C%22%E8%BF%87%22%7C%20PEL%5B%22%E8%A3%85%E8%86%9C%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,[E("span",{class:"marginnote"},'EBID 可类比为电子束版"3D 打印"：前体气体是喷在表面的墨水，电子束点到哪里，二次电子就把哪里的墨水固化成材料。束斑只有几纳米，所以补丁能长进缺口里，但边缘是缓慢过渡的三维斜坡，不是理想陡壁。')],-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[t("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"电子束诱导沉积（EBID）靠二次电子裂解吸附前体，沉积分辨率受束斑与散射限制，补丁边缘是新的 3D 物体。气体辅助刻蚀用束活化反应物种去掉材料，过刻会伤石英，引入相位坑。纳米机械是应力与切削，可能在石英上留划痕或应力双折射——AIMS 会看见。",-1)),a[6]||(a[6]=E("p",null,[E("span",{class:"marginnote"},'初学者容易以为 SEM 拍得平整就算修好了。实际上硅片"看"到的是经过光学系统的复振幅像：补丁的相位、侧壁角与透过率都参与成像，SEM 只验证几何。所以产线把 AIMS（打印视角验收）设在最后一关，问的是"能不能印好"，不是"像不像原来"。')],-1)),(l(),r(n,null,{default:e(()=>[o(A,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20DEF%5B%22%E7%BC%BA%E9%99%B7%E5%88%86%E7%B1%BB%22%5D%20--%3E%20OPAQUE%5B%22%E5%A4%9A%E4%BD%99%3A%20%E5%88%BB%E8%9A%80%20%2F%20%E7%BA%B3%E7%B1%B3%E6%9C%BA%E6%A2%B0%22%5D%0A%20%20DEF%20--%3E%20CLEAR%5B%22%E7%BC%BA%E5%A4%B1%3A%20EBID%20%E6%B2%89%E7%A7%AF%22%5D%0A%20%20OPAQUE%20--%3E%20AIMS%5B%22%E6%89%93%E5%8D%B0%E9%AA%8C%E6%94%B6%22%5D%0A%20%20CLEAR%20--%3E%20AIMS%0A%20%20AIMS%20--%3E%20PASS%5B%22%E8%A3%85%E8%86%9C%E6%88%96%E6%8A%A5%E5%BA%9F%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=i('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>修复不提高写栅分辨率，不消除雾化前体。已装 pellicle 的版修复成本更高，常先判定报废。不写某工具商标的束流表。</p><p>后课默认：可打印的修复已经做完；下一课把 pellicle 装上并检验膜与安装。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>暗缺陷去除、亮缺陷沉积；补丁必须打印验收。</li><li>多层 EUV 损伤往往不可用表面补丁恢复。</li><li>修复是局域图形化，有损伤与次数上限。</li><li>出处：e-beam 掩模修复与 nanomachining 产线通称；SPIE Photomask 修复论述。</li></ul>',5))])}const b=s(d,[["render",m]]);export{f as __pageData,b as default};
